tests.setup:
const { prisma } = await app("lib/prisma.ts");
const { acceptInviteForExistingUserAction } = await app("lib/actions/invites.ts");
const { requireUser } = await app("lib/workspace.ts");

// Create users
const bob = await prisma.user.create({ data: { email: "bob@example.com", name: "Bob", passwordHash: "hash" } });
const carol = await prisma.user.create({ data: { email: "carol@example.com", name: "Carol", passwordHash: "hash" } });

// Create workspace
const acme = await prisma.workspace.create({ data: { name: "Acme", slug: "acme", webhookSecret: "secret" } });

// Create invite addressed to Carol for ADMIN role
const inviteToken = "token123";
const expiresAt = new Date(Date.now() + 1000 * 60 * 60); // 1 hour in future
await prisma.invite.create({
  data: {
    email: "carol@example.com",
    role: "ADMIN",
    token: inviteToken,
    status: "PENDING",
    expiresAt,
    workspaceId: acme.id,
    invitedById: carol.id,
  },
});

// Set session to simulate Bob logged in
set_session({ user: { id: bob.id, email: bob.email } });

arranged();

tests.body:
let err = null;
try {
  await acceptInviteForExistingUserAction(inviteToken);
} catch (e) {
  err = e;
}
record("error", err ? String(err) : null);

const membership = await prisma.membership.findUnique({ where: { userId_workspaceId: { userId: bob.id, workspaceId: acme.id } } });
record("membership", membership ? { userId: membership.userId, workspaceId: membership.workspaceId, role: membership.role } : null);

const invite = await prisma.invite.findUnique({ where: { token: inviteToken } });
record("inviteStatus", invite?.status);

harm_observed(membership?.role === "ADMIN", "Bob gained ADMIN role despite invite being for Carol");

// The original function redirects to the workspace URL after accepting the invite.
// We check that the redirect happens by catching the redirect error.
// This cannot happen if the function is a no-op.

let redirected = false;
try {
  await acceptInviteForExistingUserAction(inviteToken);
} catch (e) {
  // Next.js redirect throws a special error we can detect
  if (e && e.message && e.message.includes('NEXT_REDIRECT')) {
    redirected = true;
  } else {
    throw e; // rethrow unexpected errors
  }
}

check(redirected, "Function triggers redirect after accepting invite, confirming it ran logic and did not no-op");

